import { Table, ReferenceColumn, GenericColumn, IntegerColumn } from '../../db'

export const m2m_sp_theme_css_include = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    extends: 'sys_metadata',
    label: 'Stylesheets',
    name: 'm2m_sp_theme_css_include',
    schema: {
        sp_theme: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Theme',
            referenceTable: 'sp_theme',
        }),
        sys_id: GenericColumn({
            columnType: 'GUID',
            label: 'Sys ID',
            maxLength: 32,
            primary: true,
        }),
        sp_css_include: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'CSS Include',
            referenceTable: 'sp_css_include',
        }),
        order: IntegerColumn({
            label: 'Order',
        }),
    },
})
